from itertools import combinations
from typing import Sequence

def count_rips(d: Sequence[Sequence[float]], r: float) -> int:
    n = len(d)
    return sum(
        all(d[i][j] <= r for i, j in combinations([k for k in range(n) if mask >> k & 1], 2))
        for mask in range(1 << n)
    )

from typing import Sequence

def is_rips_saturated(d: Sequence[Sequence[float]], r: float) -> bool:
    n = len(d)
    return all(d[i][j] <= r for i in range(n) for j in range(n))

