from math import hypot
import matplotlib.pyplot as plt
points = [(0, 0), (1, 0), (1, 1), (0, 1)]
scales = [1.0, 2 ** 0.5]
fig, axes = plt.subplots(1, 2, figsize=(9, 4))
for ax, r in zip(axes, scales):
    for i, p in enumerate(points):
        for j, q in enumerate(points[:i]):
            if hypot(p[0]-q[0], p[1]-q[1]) <= r + 1e-12:
                ax.plot([p[0], q[0]], [p[1], q[1]], color="#2563eb")
    ax.scatter(*zip(*points), s=80, color="#dc2626", zorder=3)
    ax.set(title=f"Scale r={r:.3g}", aspect="equal", xlim=(-.2,1.2), ylim=(-.2,1.2))
plt.tight_layout(); plt.show()

